function modal(h){closeModal();const m=document.createElement('div');m.id='modal';m.innerHTML='<div class="box" role="dialog" aria-modal="true">'+h+'</div>';m.addEventListener('click',e=>{if(e.target===m)closeModal()});document.body.appendChild(m);const f=m.querySelector('select,button.pri');if(f)setTimeout(()=>f.focus(),50);return m}
function closeModal(){const m=$('#modal');if(m)m.remove()}
function confirmBox(msg,yes='Ja',no='Abbrechen'){return new Promise(res=>{const m=modal('<div class="row" style="align-items:flex-start;gap:.9rem"><span class="kpi"><span class="ki g" style="display:grid">'+icon('info')+'</span></span><p class="grow" style="margin:.4rem 0 0">'+esc(msg)+'</p></div><div class="row mt2" style="justify-content:flex-end"><button class="btn" id="cn">'+esc(no)+'</button><button class="btn pri" id="cy">'+esc(yes)+'</button></div>');$('#cn',m).onclick=()=>{closeModal();res(false)};$('#cy',m).onclick=()=>{closeModal();res(true)}})}
