/* Formeln: $...$ → gestapelte Brüche (HTML) */
const TEXSYM=[['\\cdot','·'],['\\times','×'],['\\div','÷'],['\\pm','±'],['\\leq','≤'],['\\geq','≥'],['\\le','≤'],['\\ge','≥'],['\\neq','≠'],['\\approx','≈'],['\\pi','π'],['\\infty','∞'],['\\Rightarrow','⇒'],['\\rightarrow','→'],['\\to','→'],['\\%','%'],['\\,',' '],['\\;',' '],['\\quad','  '],['\\ ',' '],['\\left',''],['\\right',''],['{,}',','],['\\text',''],['\\mathrm','']];
const texSym=s=>{TEXSYM.forEach(([a,b])=>{s=s.split(a).join(b)});return s};
function pg(s,i){let d=0,j=i;for(;j<s.length;j++){if(s[j]==='{')d++;else if(s[j]==='}'){d--;if(d===0)break}}return[s.slice(i+1,j),j+1]}
function texH(s){s=texSym(s.replace(/ - /g,' − '));let o='',i=0,buf='';const fl=()=>{o+=esc(buf.replace(/[{}]/g,''));buf=''};
while(i<s.length){if(s.startsWith('\\frac{',i)){fl();let[a,j]=pg(s,i+5),[b,k]=pg(s,j);o+='<span class="fr"><span>'+texH(a)+'</span><span>'+texH(b)+'</span></span>';i=k}
else if(s.startsWith('\\sqrt{',i)){fl();let[a,j]=pg(s,i+5);o+='√<span class="rad">'+texH(a)+'</span>';i=j}
else if(s[i]==='^'&&s[i+1]==='{'){fl();let[e,j]=pg(s,i+1);o+='<sup>'+texH(e)+'</sup>';i=j}
else if(s[i]==='_'&&s[i+1]==='{'){fl();let[e,j]=pg(s,i+1);o+='<sub>'+texH(e)+'</sub>';i=j}
else{buf+=s[i];i++}}fl();return o}
function tx(t){t=String(t==null?'':t);let o='',last=0;const re=/\$([^$]*)\$/g;let m;while((m=re.exec(t))){o+=esc(t.slice(last,m.index))+'<span class="tex">'+texH(m[1])+'</span>';last=re.lastIndex}return o+esc(t.slice(last))}
const LET='ABCDEFGH';
const strip=t=>String(t).replace(/\$([^$]*)\$/g,(m,x)=>texSym(x).replace(/\\frac\{([^}]*)\}\{([^}]*)\}/g,'$1/$2').replace(/[{}\\]/g,''));

