function htmlDoc(doc){let h='';doc.B.forEach(b=>{switch(b.k){case'h1':h+='<h1>'+tx(b.t)+'</h1>';break;case'h2':h+='<h2>'+tx(b.t)+'</h2>';break;case'p':h+='<p'+(b.b?' class="b"':'')+'>'+tx(b.t)+'</p>';break;case'step':h+='<p class="st">• '+tx(b.t)+'</p>';break;case'qh':h+='<div class="qh">'+tx(b.t)+'</div>';break;case'pb':h+='<div class="pb"></div>';break;
case'img':h+='<p class="c"><img src="'+imgSrc(b.key)+'" style="width:'+b.w+'px;max-width:100%"></p>';break;case'optimg':h+='<div class="oi">'+b.keys.map((k,i)=>'<span>☐ <b>'+LET[i]+'</b> <img src="'+imgSrc(k)+'"></span>').join('')+'</div>';break;
case'opts':h+='<div class="op">'+b.t.map((t,i)=>'<span>☐ <b>'+LET[i]+'</b> '+tx(t)+'</span>').join('')+'</div>';break;case'tbl':h+='<table><caption>'+esc(b.cap)+'</caption><tr>'+b.head.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr>'+b.rows.map(r=>'<tr>'+r.map(x=>'<td>'+esc(x)+'</td>').join('')+'</tr>').join('')+'</table>';break;
case'key':h+='<table class="k"><tr>'+'<th>Nr.</th><th>Lösung</th>'.repeat(5)+'</tr>'+b.rows.map(r=>'<tr>'+r.map((x,i)=>'<td>'+(i%2?'<b>'+esc(x)+'</b>':esc(x))+'</td>').join('')+'</tr>').join('')+'</table>'}});
return'<!doctype html><html lang="de"><head><meta charset="utf-8"><title>'+esc(doc.title)+'</title><style>@page{size:Letter;margin:18mm 20mm}body{font:11pt/1.4 "Times New Roman",serif;color:#000}h1{font-size:20pt;margin:0 0 6pt}h2{font:700 14pt Arial,sans-serif;border-bottom:1.5px dotted #000;padding-bottom:3pt;margin:14pt 0 6pt;break-after:avoid}p{margin:3pt 0;text-align:justify}.b{font-weight:700}.st{margin-left:14pt;text-indent:-10pt}.qh{font-weight:700;font-size:10pt;border-top:1.5px solid #000;margin-top:10pt;padding-top:3pt;break-after:avoid}.op{display:grid;grid-template-columns:1fr 1fr;gap:2pt 14pt;margin:4pt 0;break-inside:avoid}.oi{display:grid;grid-template-columns:repeat(4,1fr);gap:4pt;margin:4pt 0;break-inside:avoid}.oi img{width:58px;vertical-align:middle}.c{text-align:center;break-inside:avoid;break-after:avoid}img{max-width:100%;height:auto}table{border-collapse:collapse;margin:4pt 0;break-inside:avoid;font-size:10pt}th,td{border:1px solid #000;padding:2pt 6pt;text-align:center}caption{font-weight:700;text-align:left}.pb{break-after:page}.wm{position:fixed;top:48%;left:0;right:0;text-align:center;font:700 42pt Arial,sans-serif;color:rgba(0,0,0,.06);transform:rotate(-28deg);pointer-events:none}.tex{font-family:"Cambria Math","STIX Two Math",serif}.fr{display:inline-flex;flex-direction:column;vertical-align:middle;text-align:center;margin:0 .15em;line-height:1.15}.fr>span:first-child{border-bottom:1.2px solid #000;padding:0 .2em}.fr>span:last-child{padding:0 .2em}.rad{border-top:1.2px solid #000}</style></head><body><div class="wm">'+esc('Lizenziert für '+wmName())+'</div>'+h+'</body></html>'}
function printDoc(doc){let f=$('#pf');if(f)f.remove();f=document.createElement('iframe');f.id='pf';f.style.cssText='position:fixed;right:0;bottom:0;width:0;height:0;border:0';f.srcdoc=htmlDoc(doc);f.onload=()=>setTimeout(()=>{try{f.contentWindow.focus();f.contentWindow.print()}catch(e){toast('Der Druckdialog konnte nicht geöffnet werden.',2600,'alert')}},700);document.body.appendChild(f)}
