Z.views.papier=el=>{const o=Z.S.dlo=Object.assign({scope:'test',test:'T01',part:'matr',n:20,order:'book',mode:'key'},Z.S.dlo||{});const opt=(v,t,c)=>'<option value="'+v+'"'+(c===v?' selected':'')+'>'+esc(t)+'</option>';
el.innerHTML=ph('Zum Ausdrucken und Offline-Lernen','Downloads','Erzeuge Übungsaufgaben als bearbeitbares Word-Dokument oder als PDF: einen ganzen Test, einen Prüfungsteil oder einen gemischten Bogen. Bilder werden nie auf zwei Seiten geteilt.')+
'<div class="card"><div class="card-h"><h3><span class="pill">1</span> Umfang festlegen</h3></div><div class="grid g2" style="gap:0 1rem"><div><label class="f" for="dsc">Umfang</label><select id="dsc" data-dl="scope">'+opt('test','Ein ganzer Test (Themen-Test oder Simulation)',o.scope)+opt('part','Ein Prüfungsteil',o.scope)+opt('mix','Gemischter Bogen aus allen Teilen',o.scope)+'</select></div><div id="dsub"></div><div><label class="f" for="dn">Anzahl der Aufgaben</label><select id="dn" data-dl="n">'+[[10,'10'],[20,'20'],[30,'30'],[50,'50'],[78,'78'],[0,'Alle']].map(x=>opt(String(x[0]),x[1],String(o.n))).join('')+'</select></div><div><label class="f" for="dor">Reihenfolge</label><select id="dor" data-dl="order">'+opt('book','Wie im Buch',o.order)+opt('random','Zufällig gemischt',o.order)+'</select></div></div></div>'+
'<div class="card mt"><div class="card-h"><h3><span class="pill">2</span> Lösungen</h3></div><div class="grid g3">'+[['q','Nur Aufgaben','Als Übungsbogen zum Ausdrucken.','file'],['key','Mit Lösungsschlüssel','Selbst auswerten nach dem Üben.','checkc'],['full','Mit Lösungswegen','Schlüssel, Schritte und Fallen.','book']].map(m=>'<label class="card flat link" style="cursor:pointer;display:flex;gap:.7rem;align-items:flex-start;padding:1rem"><input type="radio" name="dmode" data-dl="mode" value="'+m[0]+'"'+(o.mode===m[0]?' checked':'')+' style="margin-top:.3rem;accent-color:var(--navy2)"><div><b class="row" style="gap:.4rem">'+icon(m[3])+m[1]+'</b><p class="small muted" style="margin:.2rem 0 0">'+m[2]+'</p></div></label>').join('')+'</div></div>'+
'<div class="card mt"><div class="card-h"><h3><span class="pill">3</span> Format wählen</h3></div><div class="row"><button class="btn pri lg" data-act="dlgo" data-fmt="docx">'+icon('file')+' Word-Dokument erzeugen</button><button class="btn lg" data-act="dlgo" data-fmt="pdf">'+icon('printer')+' PDF erzeugen</button></div><p class="xs muted mt">PDF: Es öffnet sich der Druckdialog deines Browsers. Wähle dort „Als PDF speichern“.</p></div><div class="note mt">'+icon('shield')+'<div><strong>Hinweis zur Nutzung</strong>Die Dateien sind für dein eigenes Lernen bestimmt und tragen deinen Namen als Wasserzeichen. Bitte gib sie nicht weiter.</div></div>';dlSub()};
function dlSub(){const o=Z.S.dlo,d=$('#dsub');if(!d)return;if(o.scope==='test')d.innerHTML='<label class="f" for="dts">Test</label><select id="dts" data-dl="test">'+Z.D.tests.map(t=>'<option value="'+t.id+'"'+(o.test===t.id?' selected':'')+'>'+esc(t.lab+' · '+t.topic)+'</option>').join('')+'</select>';else if(o.scope==='part')d.innerHTML='<label class="f" for="dts">Prüfungsteil</label><select id="dts" data-dl="part">'+PARTS.map(p=>'<option value="'+p.k+'"'+(o.part===p.k?' selected':'')+'>'+esc(p.n)+'</option>').join('')+'</select>';else d.innerHTML='<p class="small muted" style="margin-top:2.6rem">Aufgaben aus allen fünf Teilen, in der gewählten Reihenfolge.</p>'}
document.addEventListener('change',e=>{const k=e.target.dataset&&e.target.dataset.dl;if(!k||!Z.S)return;Z.S.dlo[k]=k==='n'?+e.target.value:e.target.value;save();if(k==='scope')dlSub()});
Z.acts.dlgo=async e=>{const o=Z.S.dlo,fmt=e.dataset.fmt;modal('<div class="row"><span class="spin"></span><h3 style="margin:0">'+(fmt==='pdf'?'PDF':'Word-Dokument')+' wird erstellt …</h3></div><p class="small muted">Bitte einen Moment Geduld.</p>');await new Promise(r=>setTimeout(r,60));
try{const doc=buildModel(o);if(fmt==='pdf'){closeModal();printDoc(doc)}else{const blob=renderDocx(doc);dl(doc.fname+(o.mode==='full'?'-mit-loesungen':o.mode==='key'?'-mit-schluessel':'')+'.docx',blob);closeModal();toast('Datei erstellt ('+(blob.size/1048576).toFixed(1).replace('.',',')+' MB)')}touchDay();save()}catch(x){console.error(x);closeModal();modal('<h3>Das hat nicht geklappt</h3><p class="small">'+esc(x.message||String(x))+'</p><div class="row mt" style="justify-content:flex-end"><button class="btn pri" data-act="closem">Schließen</button></div>')}};

/* ===== Tastatur ===== */
document.addEventListener('keydown',e=>{if(!Z.D||e.metaKey||e.ctrlKey||e.altKey)return;const tg=e.target;if(tg&&(/^(INPUT|SELECT|TEXTAREA)$/.test(tg.tagName)))return;
if(e.key==='Escape'){if($('#zoom')){$('#zoom').remove();return}if($('#modal')){closeModal();return}document.body.classList.remove('menu');return}
if($('#modal')||$('#zoom'))return;const h=location.hash;
if(h==='#/lauf'&&Z.run&&!Z.run.done){const k=e.key.toUpperCase();const i=LET.indexOf(k);const nOpt=$$('#qc [data-pick]').length;if(i>=0&&i<nOpt&&k.length===1){e.preventDefault();const b=$$('#qc [data-pick]')[i];if(!b.disabled)pickAns(i);return}
 if(e.key==='ArrowRight'||(e.key==='Enter'&&tg.tagName!=='BUTTON')){const b=$('[data-act=next]:not([disabled]),[data-act=nextpart],[data-act=finish]');if(b&&(e.key!=='ArrowRight'||b.dataset.act==='next')){e.preventDefault();b.click()}return}
 if(e.key==='ArrowLeft'){e.preventDefault();Z.acts.prev();return}}
if(h.startsWith('#/karten')&&$('#fc')){if(e.key===' '||(e.key==='Enter'&&tg.id==='fc')){e.preventDefault();Z.acts.cflip();return}if(Z.cflip&&['1','2','3'].includes(e.key)){e.preventDefault();const b=$('[data-act=crate][data-r="'+(+e.key-1)+'"]');if(b)b.click()}}});

/* ===== Start ===== */
Z.acts.menu=()=>document.body.classList.toggle('menu');
Z.acts.theme=()=>{const cur=document.documentElement.dataset.theme;Z.S.set.dark=cur==='dark'?'light':'dark';save(true);applyPrefs()};
Z.acts.eye=()=>{const p=$('#pw'),b=$('.eye');p.type=p.type==='password'?'text':'password';b.innerHTML=icon(p.type==='password'?'eye':'eyeoff');b.setAttribute('aria-label',p.type==='password'?'Eingabe anzeigen':'Eingabe verbergen')};
document.addEventListener('click',e=>{const a=e.target.closest('[data-act]');if(!a)return;const f=Z.acts[a.dataset.act];if(f){e.preventDefault();f(a,e)}});
Z.S=loadState();applyPrefs();matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applyPrefs);
$('#loginForm').addEventListener('submit',doLogin);
gateStart();
(async()=>{let pw=null;try{pw=localStorage.getItem('dl_pw')||sessionStorage.getItem('dl_pw')}catch(e){}if(!pw)return;try{const r=await unlock(pw);await enterApp(r.data,r.norm,!!localStorage.getItem('dl_pw'))}catch(e){try{localStorage.removeItem('dl_pw');sessionStorage.removeItem('dl_pw')}catch(_){}}})();
